repo.trades.py:
"""Trade records."""


class Trade:
    def __init__(self, desk, volume):
        self.desk = desk
        self.volume = volume

    def __repr__(self):
        return "Trade(%r, %r)" % (self.desk, self.volume)


ROWS = [('energy', 13), ('metals', 29), ('bonds', 17), ('metals', 4), ('fx', 10), ('bonds', 34)]


def load_trades():
    """Yield the stored trades one at a time."""
    for desk, volume in ROWS:
        yield Trade(desk, volume)

repo.cumulative.py:
"""Running totals over trades."""


def running_volume(trades):
    """Return the running total of volume after each trade, in order."""
    out = []
    total = 0
    for i in range(len(trades) - 1):
        total += trades[i].volume
        out.append(total)
    return out


def final_volume(trades):
    """Return the total volume of all trades, or 0 when there are none."""
    totals = running_volume(trades)
    return totals[-1] if totals else 0


def describe_trade(trade):
    """Return a one-line description of a trade."""
    return "%s: %s" % (trade.desk, trade.volume)


def group_by_desk(trades):
    """Return a dict from desk to the list of trades with that desk."""
    groups = {}
    for x in trades:
        groups.setdefault(x.desk, []).append(x)
    return groups

